// IMA ADPCM: a 16-bit predictor followed by packed 4-bit deltas.
const steps=[7,8,9,10,11,12,13,14,16,17,19,21,23,25,28,31,34,37,41,45,50,55,60,66,73,80,88,97,107,118,130,143,157,173,190,209,230,253,279,307,337,371,408,449,494,544,598,658,724,796,876,963,1060,1166,1282,1411,1552,1707,1878,2066,2272,2499,2749,3024,3327,3660,4026,4428,4871,5358,5894,6484,7132,7845,8630,9493,10442,11487,12635,13899,15289,16818,18500,20350,22385,24623,27086,29794,32767];
const shifts=[-1,-1,-1,-1,2,4,6,8];
const clamp=(v,min,max)=>Math.max(min,Math.min(max,v));
export function encode(samples){const bytes=new Uint8Array(6+Math.ceil((samples.length-1)/2));const view=new DataView(bytes.buffer);view.setUint32(0,samples.length,true);let predictor=clamp(Math.round(samples[0]*32767),-32768,32767),index=0;view.setInt16(4,predictor,true);for(let i=1;i<samples.length;i++){let delta=Math.round(samples[i]*32767)-predictor;let code=delta<0?8:0;delta=Math.abs(delta);let step=steps[index],diff=step>>3;if(delta>=step){code|=4;delta-=step;diff+=step;}if(delta>=step>>1){code|=2;delta-=step>>1;diff+=step>>1;}if(delta>=step>>2){code|=1;diff+=step>>2;}predictor=clamp(predictor+(code&8?-diff:diff),-32768,32767);index=clamp(index+shifts[code&7],0,88);bytes[6+((i-1)>>1)]|=code<<(((i-1)&1)*4);}return bytes;}
export function decode(bytes){const view=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);const length=view.getUint32(0,true);if(length<1||length>128000||bytes.length!==6+Math.ceil((length-1)/2))throw Error('Invalid sample');const out=new Float32Array(length);let predictor=view.getInt16(4,true),index=0;out[0]=predictor/32768;for(let i=1;i<length;i++){const code=(bytes[6+((i-1)>>1)]>>(((i-1)&1)*4))&15,step=steps[index];let diff=(step>>3)+(code&4?step:0)+(code&2?step>>1:0)+(code&1?step>>2:0);predictor=clamp(predictor+(code&8?-diff:diff),-32768,32767);index=clamp(index+shifts[code&7],0,88);out[i]=predictor/32768;}return out;}
export function trim(samples,rate){let peak=0;for(const x of samples)peak=Math.max(peak,Math.abs(x));if(peak<.008)throw Error('Too quiet. Move closer and try again.');const threshold=Math.max(.003,peak*.015);let start=0,end=samples.length-1;while(start<end&&Math.abs(samples[start])<threshold)start++;while(end>start&&Math.abs(samples[end])<threshold)end--;start=Math.max(0,start-Math.round(rate*.008));end=Math.min(samples.length,end+Math.round(rate*.035));const out=samples.slice(start,end);if(out.length<rate*.035)throw Error('Sound too short. Try a longer sound.');const gain=Math.min(8,.88/peak);const fade=Math.min(Math.round(rate*.004),out.length/2);for(let i=0;i<out.length;i++)out[i]*=gain*Math.min(1,i/fade,(out.length-1-i)/fade);return out;}
export function detectPitch(data,rate){const size=Math.min(4096,data.length);if(size<512)return null;let bestResult=null;for(const fraction of [.1,.35,.6]){const offset=Math.min(Math.floor(data.length*fraction),data.length-size);const frame=data.subarray(offset,offset+size);const minLag=Math.floor(rate/1100),maxLag=Math.min(Math.floor(rate/65),Math.floor(size/2));const correlations=[];let energy=0;for(const x of frame)energy+=x*x;if(energy/size<.0001)continue;for(let lag=minLag;lag<=maxLag;lag++){let cross=0,a=0,b=0;for(let i=0;i<size-maxLag;i++){cross+=frame[i]*frame[i+lag];a+=frame[i]**2;b+=frame[i+lag]**2;}correlations[lag]=cross/Math.sqrt(a*b||1);}let highest=0;for(let lag=minLag+1;lag<maxLag;lag++)highest=Math.max(highest,correlations[lag]);if(highest<.8)continue;for(let lag=minLag+1;lag<maxLag;lag++){const c=correlations[lag];if(c>Math.max(.8,highest*.96)&&c>correlations[lag-1]&&c>=correlations[lag+1]){const shift=.5*(correlations[lag-1]-correlations[lag+1])/(correlations[lag-1]-2*c+correlations[lag+1]||1);const result={frequency:rate/(lag+shift),confidence:c};if(!bestResult||c>bestResult.confidence)bestResult=result;break;}}}return bestResult?.frequency??null;}
